INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32911, 'Matthew 13:14', 'Matthew', 13, 14, 'نو د اشعیا پیغمبر پېشګویي د هغوی په هکله پوره کیږي چې وایي: تاسو به یې بیا بیا اورئ خو پوه به نه شئ، تاسو به ګورئ خو څه به نه وینئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_14.mp3', '', 1761754199, 1761754199),
(32912, 'Matthew 13:15', 'Matthew', 13, 15, 'ځکه چې د دې خلکو زړونه سخت شوي دي او په غوږو درانه دي. سترګې یې پټې شوې دي، که نه، نو سترګو به یې لیدل، غوږونو به یې اورېدل، په زړونو کې به پوهېدل او ماته به بېرته راګرځېدلي وای او ما به شفا ورکړې وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_15.mp3', '', 1761754199, 1761754199),
(32913, 'Matthew 13:16', 'Matthew', 13, 16, 'خو ستاسو سترګې بختورې دي، ځکه چې ویني او غوږونه مو بختور دي ځکه چې اوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_16.mp3', '', 1761754199, 1761754199),
(32914, 'Matthew 13:17', 'Matthew', 13, 17, 'په یقین سره زه تاسو ته دا وایم چې ډېرو پیغمبرانو او نېکو خلکو دا ارمان درلود چې هغه څه وویني چې تاسو یې وینئ، خو ویې نه لیدل او هغه څه واوري چې تاسو یې اورئ، خو هغوی وانه ورېدل. د بزګر مثال (مرقوس ۴‏:‌۱۳‌‏-‌۲۰ او لوقا ۸‏:‌۱۱‌‏-‌۱۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_17.mp3', '', 1761754199, 1761754199),
(32915, 'Matthew 13:18', 'Matthew', 13, 18, 'نو بیا د بزګر د مثال معنی واورئ:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_18.mp3', '', 1761754199, 1761754199),
(32916, 'Matthew 13:19', 'Matthew', 13, 19, 'کله چې څوک د خدای د پاچاهۍ په هکله پیغام واوري، خو ورباندې پوه نه شي نو هغه د داسې تخم په شان دی چې په لاره کې ولویږي. شیطان راشي او څه چې د هغوی په زړونو کې کرل شوي وي هغه وتښتوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_19.mp3', '', 1761754199, 1761754199),
(32917, 'Matthew 13:20', 'Matthew', 13, 20, 'په تیږه لرونکې ځمکه کې کرل شوی تخم د هغه چا په مثال دی چې پیغام واوري او سمدلاسه یې په خوشحالۍ سره قبول کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_20.mp3', '', 1761754199, 1761754199),
(32918, 'Matthew 13:21', 'Matthew', 13, 21, 'خو څرنګه چې په هغوی کې یې ریښې نه وي نیولې، نو هغه د زیات وخت دپاره نه پاتې کیږي. نو بیا کله چې د پیغام له امله ورباندې سختي راشي یا وځوریږي، نو زر خپل ایمان له لاسه ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_21.mp3', '', 1761754199, 1761754199),
(32919, 'Matthew 13:22', 'Matthew', 13, 22, 'په اغزو کې لوېدلي تخم د هغه چا په مثال دی چې پیغام اوري، خو د ژوند اندېښنې او د شتمنۍ سره مینه د پیغام مخه نیسي او حاصل نه ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_22.mp3', '', 1761754199, 1761754199),
(32920, 'Matthew 13:23', 'Matthew', 13, 23, 'خو کوم تخم چې په ښه خاوره کې کرل شوی وي هغه د هغه چا په مثال دی چې پیغام اوري او ورباندې پوهیږي او هغه سل چنده او شپېته چنده او دېرش چنده حاصل هم ورکوي.» د جودرو مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_23.mp3', '', 1761754199, 1761754199),
(32921, 'Matthew 13:24', 'Matthew', 13, 24, 'عیسی هغوی ته یو بل مثال راوړ: «اسماني پاچاهي د هغه سړي سره پرتله شوې ده چې په خپل پټي کې یې ښه تخم وکرلو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_24.mp3', '', 1761754199, 1761754199),
(32922, 'Matthew 13:25', 'Matthew', 13, 25, 'خو یوه شپه کله چې ټول ویده وو، نو دښمن یې راغی او د غنمو په منځ کې ورته جودر وشیندل او لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_25.mp3', '', 1761754199, 1761754199),
(32923, 'Matthew 13:26', 'Matthew', 13, 26, 'کله چې غنم شنه شول او وږي یې ونیول، نو جودر هم په کې راښکاره شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_26.mp3', '', 1761754199, 1761754199),
(32924, 'Matthew 13:27', 'Matthew', 13, 27, 'نو د هغه زمیندار نوکران خپل بادار ته راغلل او ورته ویې ویل: ‹ای باداره، ایا تا په خپل پټي کې ښه تخم نه ؤ کرلی؟ نو بیا دا جودر په کې له کومه شول؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_27.mp3', '', 1761754199, 1761754199),
(32925, 'Matthew 13:28', 'Matthew', 13, 28, 'هغه ورته په ځواب کې وویل چې دا د دښمن کار دی. نوکرانو ورته وویل: ‹ایا مونږ لاړ شو او هغه جودر وباسو؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_28.mp3', '', 1761754199, 1761754199),
(32926, 'Matthew 13:29', 'Matthew', 13, 29, 'خو هغه ورته ځواب ورکړ چې نه، هسې نه چې د جودرو د ویستلو سره غنم هم ورسره وباسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_29.mp3', '', 1761754199, 1761754199),
(32927, 'Matthew 13:30', 'Matthew', 13, 30, 'پرېږده چې دواړه یوځای لوی شي، نو د لو په وخت کې به لوګرو ته ووایم چې لومړی جودر راټول کړي او د سوځولو دپاره یې ګېډۍ کړي او بیا غنم راټول کړي او زما ګودام ته یې راوړي.» د شړشمو د تخم مثال (مرقوس ۴‏:‌۳۰‌‏-‌۳۲ او لوقا ۱۳‏:‌۱۸‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_30.mp3', '', 1761754199, 1761754199),
(32928, 'Matthew 13:31', 'Matthew', 13, 31, 'عیسی هغوی ته یو بل مثال هم راوړ او ویې ویل: «اسماني پاچاهي د شړشمو د تخم په شان ده چې یو سړی هغه واخلي او په خپل پټي کې یې وکري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_31.mp3', '', 1761754199, 1761754199),
(32929, 'Matthew 13:32', 'Matthew', 13, 32, 'که څه هم دا تخم د نورو ټولو تخمونو څخه ډېر وړوکی دی، خو کله چې وده وکړي، نو د باغ د ټولو بوټو څخه لوی شي او ونه ترې جوړه شي، نو مرغان راشي او په څانګو کې یې ځالې جوړې کړي.» د خمیرې مثال (لوقا ۱۳‏:‌۲۰‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_32.mp3', '', 1761754199, 1761754199),
(32930, 'Matthew 13:33', 'Matthew', 13, 33, 'عیسی هغوی ته بل مثال راوړ او ویې ویل: «اسماني پاچاهي د هغې خمیرې په شان ده چې یوه ښځه هغه واخلي او د درې پیمانې اوړو سره یې ګډه کړي، ترڅو هغه ټول خمیره شي.» عیسی د مثالونو څخه کار اخلي (لوقا ۱۳‏:‌۲۰‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_33.mp3', '', 1761754199, 1761754199),
(32931, 'Matthew 13:34', 'Matthew', 13, 34, 'عیسی دا ټول شیان خلکو ته په مثالونو کې بیانول او یوه خبره یې بې‌مثالونو نه کوله', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_34.mp3', '', 1761754199, 1761754199),
(32932, 'Matthew 13:35', 'Matthew', 13, 35, 'ترڅو د پیغمبر هغه پېشګویي رښتیا شي چې ویلي یې وو: زه به په مثالونو کې خبرې وکړم او هغه شیان به بیان کړم چې د نړۍ د پیدایښت راهیسې پټ ساتل شوي دي. د جودرو د مثال روښانه کول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_35.mp3', '', 1761754199, 1761754199),
(32933, 'Matthew 13:36', 'Matthew', 13, 36, 'بیا عیسی خلک رخصت کړل او خپله هم کور ته لاړ. شاګردان یې راغلل او ورته ویې ویل: «مونږ ته د غنمو په پټي کې د جودرو د مثال معنی بیان کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_36.mp3', '', 1761754199, 1761754199),
(32934, 'Matthew 13:37', 'Matthew', 13, 37, 'هغه ځواب ورکړ: «هغه څوک چې ښه تخم کري، هغه د انسان زوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_37.mp3', '', 1761754199, 1761754199),
(32935, 'Matthew 13:38', 'Matthew', 13, 38, 'پټی دا نړۍ ده، د ښه تخم معنی د اسماني پاچاهۍ خلک دي او جودر د شیطان پیروان دي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_38.mp3', '', 1761754199, 1761754199),
(32936, 'Matthew 13:39', 'Matthew', 13, 39, 'او هغه دښمن چې جودر یې کرلي دي هغه شیطان دی، د حاصل د راټولولو وخت اخره زمانه ده او لوګرې فرښتې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_39.mp3', '', 1761754199, 1761754199),
(32937, 'Matthew 13:40', 'Matthew', 13, 40, 'لکه څنګه چې جودر راټولیږي او په اور کې سوځول کیږي، نو په اخره زمانه کې به همداسې وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_40.mp3', '', 1761754199, 1761754199),
(32938, 'Matthew 13:41', 'Matthew', 13, 41, 'د انسان زوی به خپلې فرښتې راولېږي او د هغه د پاچاهۍ نه به هغه ټول خلک چې د خلکو د ګناه سبب کیږي راټول کړي او همدارنګه هغه ټول خلک چې بدکاره دي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_41.mp3', '', 1761754199, 1761754199),
(32939, 'Matthew 13:42', 'Matthew', 13, 42, 'او هغوی به په سور تنور کې واچوي یعنې هغه ځای ته چې هلته به خلک ژاړي او خپل غاښونه به چیچي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_42.mp3', '', 1761754199, 1761754199),
(32940, 'Matthew 13:43', 'Matthew', 13, 43, 'بیا به نېک خلک د خپل پلار په پاچاهۍ کې لکه د لمر په شان ځلیږي. که څوک غوږونه لري، نو هغه دې واوري. د پټې خزانې مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_43.mp3', '', 1761754199, 1761754199),
(32941, 'Matthew 13:44', 'Matthew', 13, 44, 'اسماني پاچاهي د هغې خزانې په شان ده چې په پټي کې پټه شوې وي او یو سړی هغه پیدا کړي او بېرته یې ښخه کړي او د خوشحالۍ نه ځي او خپل ټول شیان خرڅوي او بېرته راځي او هغه پټی اخلي. د مرغلرو مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_44.mp3', '', 1761754199, 1761754199),
(32942, 'Matthew 13:45', 'Matthew', 13, 45, 'په همدې ډول اسماني پاچاهي د هغه سوداګر په شان ده چې د قیمتي مرغلرو پسې ګرځي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_45.mp3', '', 1761754199, 1761754199),
(32943, 'Matthew 13:46', 'Matthew', 13, 46, 'چې کله یې ډېرې ارزښتناکې مرغلرې پیدا کړې، نو ځي او خپل ټول شیان خرڅوي او هغه مرغلرې اخلي. د جال مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_46.mp3', '', 1761754199, 1761754199),
(32944, 'Matthew 13:47', 'Matthew', 13, 47, 'همدارنګه اسماني پاچاهي د هغه جال په شان ده چې ماهيګیران هغه په بحیرې کې واچوي او ډول ډول ماهیان ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_47.mp3', '', 1761754199, 1761754199),
(32945, 'Matthew 13:48', 'Matthew', 13, 48, 'کله چې جال د ماهیانو څخه ډک شو، نو غاړې ته یې راووېست او بیا ورته کښېناستل او په دوه برخو یې ووېشل، ښه ماهیان یې په ټوکریو کې واچول او خراب یې ایسته وغورځول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_48.mp3', '', 1761754199, 1761754199),
(32946, 'Matthew 13:49', 'Matthew', 13, 49, 'په اخره زمانه کې به همداسې وي. فرښتې به راشي او بدکاران به له نېکو خلکو څخه بېل کړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_49.mp3', '', 1761754199, 1761754199),
(32947, 'Matthew 13:50', 'Matthew', 13, 50, 'او هغوی به سور تنور ته وروغورځوي یعنې هغه ځای ته چې هلته به خلک ژاړي او خپل غاښونه به چیچي.» د نویو او زړو شیانو په هکله تعلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_50.mp3', '', 1761754199, 1761754199),
(32948, 'Matthew 13:51', 'Matthew', 13, 51, 'عیسی د شاګردانو څخه پوښتنه وکړه: «ایا تاسو په دې ټولو شیانو پوهېږئ؟» هغوی وویل: «هو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_51.mp3', '', 1761754199, 1761754199),
(32949, 'Matthew 13:52', 'Matthew', 13, 52, 'عیسی هغوی ته وویل: «د شریعت هر ښوونکی چې د اسمان په پاچاهۍ کې شاګرد شي، نو هغه د هغه کور د خاوند په شان دی چې د خپل ګودام څخه نوي او زاړه شیان راوباسي.» د ناصرې خلک عیسی نه مني (مرقوس ۶‏:‌۱‌‏-‌۶ او لوقا ۴‏:‌۱۶‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_52.mp3', '', 1761754199, 1761754199),
(32950, 'Matthew 13:53', 'Matthew', 13, 53, 'کله چې عیسی دا مثالونه پای ته ورسول، نو د هغه ځای څخه روان شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_53.mp3', '', 1761754199, 1761754199),
(32951, 'Matthew 13:54', 'Matthew', 13, 54, 'او خپل وطن ته راغی او هلته په کنیسه کې یې خلکو ته داسې تعلیم ورکاوه چې ټول حیران شول او یو بل ته یې سره وویل: «دې سړي دا حکمت او د دې معجزو د ښودلو قدرت له کوم ځایه پیدا کړی دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_54.mp3', '', 1761754199, 1761754199),
(32952, 'Matthew 13:55', 'Matthew', 13, 55, 'ایا هغه د نجار زوی نه دی؟ ایا د مور نوم یې مریم نه دی؟ ایا یعقوب، یوسف، شمعون او یهودا د هغه ورونه نه دي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_55.mp3', '', 1761754199, 1761754199),
(32953, 'Matthew 13:56', 'Matthew', 13, 56, 'ایا د هغه ټولې خویندې دلته زمونږ سره نه اوسیږي؟ نو بیا دا ټولې خبرې هغه له کوم ځای نه زده کړي دي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_56.mp3', '', 1761754199, 1761754199),
(32954, 'Matthew 13:57', 'Matthew', 13, 57, 'نو هغوی عیسی قبول نه کړ. خو عیسی هغوی ته وویل: «د یو پیغمبر په هرځای کې درناوی کیږي، خو په خپل وطن او خپله کورنۍ کې نه کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_57.mp3', '', 1761754199, 1761754199),
(32955, 'Matthew 13:58', 'Matthew', 13, 58, 'عیسی د هغوی د بې‌ایمانۍ له امله په هغه ځای کې ډېرې معجزې ونه ښودلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew13_verse_58.mp3', '', 1761754199, 1761754199),
(32956, 'Matthew 24:1', 'Matthew', 24, 1, 'کله چې عیسی د خدای د کور څخه روان شو، نو شاګردان یې ورته راغلل چې د هغه پام د خدای د کور ودانۍ ته راواړوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_1.mp3', '', 1761754199, 1761754199),
(32957, 'Matthew 24:2', 'Matthew', 24, 2, 'خو هغه وویل: «ایا دا ټولې ودانۍ وینئ؟ په یقین سره زه تاسو ته دا وایم چې دلته به یوه تیږه هم په بله تیږه پاتې نه شي او ټولې به راونړیږي.» د اخرې زمانې نښې (مرقوس ۱۳‏:‌۳‌‏-‌۱۳ او لوقا ۲۱‏:‌۷‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_2.mp3', '', 1761754199, 1761754199),
(32958, 'Matthew 24:3', 'Matthew', 24, 3, 'عیسی د زیتون په غره کې ناست ؤ چې شاګردان یې ورته راغلل او په پټه یې ورته وویل: «مونږ ته ووایه چې دا هرڅه به کله وشي؟ او ستا د راتګ او اخرې زمانې نښه به کومه وي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_3.mp3', '', 1761754199, 1761754199),
(32959, 'Matthew 24:4', 'Matthew', 24, 4, 'عیسی ځواب ورکړ: «پام کوئ چې څوک مو بې‌لارې نه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_4.mp3', '', 1761754199, 1761754199),
(32960, 'Matthew 24:5', 'Matthew', 24, 5, 'ځکه چې ډېر به زما په نوم راشي او وایي به چې زه مسیح یم او ډېر خلک به بې‌لارې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_5.mp3', '', 1761754199, 1761754199),
(32961, 'Matthew 24:6', 'Matthew', 24, 6, 'تاسو به د جګړې غږ د نژدې نه او د لېرې نه د جنګ اوازې اورئ، خو ګورئ چې وارخطا نه شئ، ځکه چې دا شیان به خامخا پېښیږي، خو دا د دې معنی نه لري چې اخرنی وخت رارسېدلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_6.mp3', '', 1761754199, 1761754199),
(32962, 'Matthew 24:7', 'Matthew', 24, 7, 'یو قوم به د بل قوم سره جنګیږي او یوه پاچاهي به د بلې پاچاهۍ سره جنګیږي او د نړۍ په ډېرو ځایونو کې به قحطي او زلزلې راشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_7.mp3', '', 1761754199, 1761754199),
(32963, 'Matthew 24:8', 'Matthew', 24, 8, 'خو دا ټول به د لنګون د دردونو د پیل کېدلو په شان وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_8.mp3', '', 1761754199, 1761754199),
(32964, 'Matthew 24:9', 'Matthew', 24, 9, 'کله چې دا هرڅه پېښ شول، نو تاسو به ونیول شئ او وبه ځورول شئ او بیا به ووژل شئ او زما د نوم په خاطر به د ټولو قومونو خلک ستاسو څخه کرکه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_9.mp3', '', 1761754199, 1761754199),
(32965, 'Matthew 24:10', 'Matthew', 24, 10, 'نو بیا به ډېر خپل ایمان له لاسه ورکړي او یو د بل سره به خیانت کوي او یو د بل څخه به کرکه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_10.mp3', '', 1761754199, 1761754199),
(32966, 'Matthew 24:11', 'Matthew', 24, 11, 'ډېر جعلي پیغمبران به راپیدا شي او ډېر خلک به بې‌لارې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_11.mp3', '', 1761754199, 1761754199),
(32967, 'Matthew 24:12', 'Matthew', 24, 12, 'بدکاري به دومره زیاته شي چې د خلکو مینه به یو د بله سره ورکه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_12.mp3', '', 1761754199, 1761754199),
(32968, 'Matthew 24:13', 'Matthew', 24, 13, 'خو څوک چې تر اخره پورې ټینګ پاتې شي هغه به خلاصون ومومي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_13.mp3', '', 1761754199, 1761754199),
(32969, 'Matthew 24:14', 'Matthew', 24, 14, 'او د اسماني پاچاهۍ زېری به په ټوله نړۍ کې خپور شي، ترڅو د ټولو قومونو دپاره شاهدي اوسي او بیا به نړۍ ختمه شي. د اخرې زمانې هیبتناکه وېره (مرقوس ۱۳‏:‌۱۴‌‏-‌۲۳ او لوقا ۲۱‏:‌۲۰‌‏-‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_14.mp3', '', 1761754199, 1761754199),
(32970, 'Matthew 24:15', 'Matthew', 24, 15, 'نو کله چې تاسو هغه نجس شی چې د بربادۍ سبب ګرځي او سپېڅلی ځای ناپاکه کوي او دانیال نبي د هغو په هکله خبرې کړي دي، ووینئ. (لوستونکي دې پوه شي چې د دې معنی څه ده.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_15.mp3', '', 1761754199, 1761754199),
(32971, 'Matthew 24:16', 'Matthew', 24, 16, 'نو څوک چې په یهودیې کې وي هغه دې غرونو ته وتښتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_16.mp3', '', 1761754199, 1761754199),
(32972, 'Matthew 24:17', 'Matthew', 24, 17, 'که څوک د بام په سر وي، نو هغه دې د کور د سامان د وړلو دپاره نه راښکته کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_17.mp3', '', 1761754199, 1761754199),
(32973, 'Matthew 24:18', 'Matthew', 24, 18, 'که څوک په پټي کې وي هغه دې د خپلې چپنې پسې بېرته کور ته نه ورځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_18.mp3', '', 1761754199, 1761754199),
(32974, 'Matthew 24:19', 'Matthew', 24, 19, 'افسوس د هغو ښځو په حال چې په هغو ورځو کې امیدوارې وي او هغو میندو په حال چې خپلو ماشومانو ته شیدې ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_19.mp3', '', 1761754199, 1761754199),
(32975, 'Matthew 24:20', 'Matthew', 24, 20, 'دعا کوئ چې ستاسو تېښته په ژمي کې او یا د سبت په ورځ نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_20.mp3', '', 1761754199, 1761754199),
(32976, 'Matthew 24:21', 'Matthew', 24, 21, 'ځکه چې په هغه وخت کې به داسې سخت مصیبت رامنځته شي چې د نړۍ له پیل څخه تر‌اوسه پورې نه دی راغلی او نه به بیا راشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_21.mp3', '', 1761754199, 1761754199),
(32977, 'Matthew 24:22', 'Matthew', 24, 22, 'که چېرې خدای هغه ورځې لنډې کړې نه وای نو هېڅوک به ژوندی پاتې شوی نه وای، خو خدای به د خپلو غوره شویو خلکو په خاطر هغه ورځې لنډې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_22.mp3', '', 1761754199, 1761754199),
(32978, 'Matthew 24:23', 'Matthew', 24, 23, 'که په هغه وخت کې څوک تاسو ته ووایي: ‹ګورئ، مسیح دلته دی یا هلته دی،› نو باور ورباندې مه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_23.mp3', '', 1761754199, 1761754199),
(32979, 'Matthew 24:24', 'Matthew', 24, 24, 'ځکه چې داسې کسان به پیدا شي چې په دروغو به دعوه کوي چې مسیح او پیغمبران دي او لویې معجزې به وښایي او حیرانوونکي کارونه به کوي، د دې دپاره که ممکن وي نو د خدای غوره شوي خلک به هم بې‌لارې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_24.mp3', '', 1761754199, 1761754199),
(32980, 'Matthew 24:25', 'Matthew', 24, 25, 'نو پام کوئ، تاسو مې له مخکې نه خبر کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_25.mp3', '', 1761754199, 1761754199),
(32981, 'Matthew 24:26', 'Matthew', 24, 26, 'نو که چېرې څوک تاسو ته ووایي چې مسیح په دښته کې دی، نو هلته مه ځئ او یا درته ووایي چې هغه په یو پټ ځای کې دی نو باور ورباندې مه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_26.mp3', '', 1761754199, 1761754199),
(32982, 'Matthew 24:27', 'Matthew', 24, 27, 'ځکه لکه څنګه چې برېښنا له ختیځې خوا راځي نو رڼا یې تر لوېدیځه پورې ځلیږي، نو د انسان د زوی راتګ به هم همداسې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_27.mp3', '', 1761754199, 1761754199),
(32983, 'Matthew 24:28', 'Matthew', 24, 28, 'چېرته چې مرداره وي هلته ټپوسان راټولیږي. د انسان د زوی راتلل (مرقوس ۱۳‏:‌۲۴‌‏-‌۲۷ او لوقا ۲۱‏:‌۲۵‌‏-‌۲۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_28.mp3', '', 1761754199, 1761754199),
(32984, 'Matthew 24:29', 'Matthew', 24, 29, 'څنګه چې د مصیبت هغه ورځې تېرې شي، نو سمدلاسه به لمر تیاره شي او سپوږمۍ به نوره رڼا نه ورکوي، ستوري به د اسمان څخه راولویږي او اسماني موجودات به ولړزیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_29.mp3', '', 1761754199, 1761754199),
(32985, 'Matthew 24:30', 'Matthew', 24, 30, 'هغه وخت به په اسمان کې د انسان د زوی د راتللو نښې راښکاره شي او د نړۍ ټول قومونه به ویر کوي او هغوی به وویني چې د انسان زوی به د قدرت او زیات جلال سره د اسمان په ورېځو کې راروان وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_30.mp3', '', 1761754199, 1761754199),
(32986, 'Matthew 24:31', 'Matthew', 24, 31, 'هغه به خپلې فرښتې چې په لوړ اواز سره به سرنی وهي راولېږي او هغوی به د نړۍ د یو سر نه تر بله سره پورې خپل غوره شوي خلک راټول کړي. د انځر د ونې څخه عبرت اخیستل (مرقوس ۱۳‏:‌۲۸‌‏-‌۳۱ او لوقا ۲۱‏:‌۲۹‌‏-‌۳۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_31.mp3', '', 1761754199, 1761754199),
(32987, 'Matthew 24:32', 'Matthew', 24, 32, 'د انځر د ونې څخه عبرت واخلئ. کله چې د هغې څانګې غوټۍ ونیسي او پاڼې وکړي، نو تاسو پوهېږئ چې اوړی رانژدې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_32.mp3', '', 1761754199, 1761754199),
(32988, 'Matthew 24:33', 'Matthew', 24, 33, 'نو په همدې ډول کله چې تاسو دا ټول شیان ووینئ، نو پوه شئ چې هغه وخت نژدې دی بلکې رارسېدلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_33.mp3', '', 1761754199, 1761754199),
(32989, 'Matthew 24:34', 'Matthew', 24, 34, 'په یقین سره زه تاسو ته دا وایم چې دا نسل به تر هغې پورې له منځه لاړ نه شي، ترڅو دا ټولې پېښې رامنځته شوې نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_34.mp3', '', 1761754199, 1761754199),
(32990, 'Matthew 24:35', 'Matthew', 24, 35, 'ځمکه او اسمان به له منځه لاړ شي، خو زما خبرې به هېڅکله له منځه لاړې نه شي. د انسان د زوی د راتګ وخت (مرقوس ۱۳‏:‌۳۲‌‏-‌۳۷ او لوقا ۱۷‏:‌۲۶‌‏-‌۳۰، ۱۷‏:‌۳۴‌‏-‌۳۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_35.mp3', '', 1761754199, 1761754199),
(32991, 'Matthew 24:36', 'Matthew', 24, 36, 'خو د هغې ورځې او هغه ساعت نه هېڅوک خبر نه دي، نه د اسمان فرښتې او نه زوی، خو یوازې پلار پرې خبر دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_36.mp3', '', 1761754199, 1761754199),
(32992, 'Matthew 24:37', 'Matthew', 24, 37, 'لکه څنګه چې د نوح په زمانه کې شوي وو، نو همداسې به د انسان د زوی د راتګ په وخت کې وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_37.mp3', '', 1761754199, 1761754199),
(32993, 'Matthew 24:38', 'Matthew', 24, 38, 'د سېلاب د راتللو څخه مخکې تر هغې ورځې پورې چې نوح کشتۍ ته ننوت، نو خلکو به خوړل او څښل او ودونه به یې کول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_38.mp3', '', 1761754199, 1761754199),
(32994, 'Matthew 24:39', 'Matthew', 24, 39, 'دوی تر هغه وخته نه پوهېدل چې څه به کیږي، ترڅو سېلاب راغی او هغوی ټول یې له منځه یووړل. نو د انسان د زوی راتګ به هم همداسې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_39.mp3', '', 1761754199, 1761754199),
(32995, 'Matthew 24:40', 'Matthew', 24, 40, 'نو په هغه وخت کې که چېرې دوه کسان په پټي کې وي، نو یو به یې بوتلل شي او بل به پرېښودل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_40.mp3', '', 1761754199, 1761754199),
(32996, 'Matthew 24:41', 'Matthew', 24, 41, 'او د دوو ښځو څخه چې یوځای سره میچن کوي یوه به یې بوتلل شي او بله به پرېښودل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_41.mp3', '', 1761754199, 1761754199),
(32997, 'Matthew 24:42', 'Matthew', 24, 42, 'نو بېداره اوسئ، ځکه چې تاسو نه پوهېږئ چې ستاسو څښتن به په کومه ورځ راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_42.mp3', '', 1761754199, 1761754199),
(32998, 'Matthew 24:43', 'Matthew', 24, 43, 'خو په دې پوه شئ، که چېرې د کور خاوند په دې پوهېدلی چې غل د شپې په کوم وخت کې راځي، نو هغه به ویښ پاتې شوی وای او غل به یې نه پرېښود چې کور ته یې ورننوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_43.mp3', '', 1761754199, 1761754199),
(32999, 'Matthew 24:44', 'Matthew', 24, 44, 'نو تاسو هم باید تیار اوسئ، ځکه چې د انسان زوی به په هغه وخت کې راشي چې ستاسو په خیال کې به هم نه وي. وفادار او بې‌وفا نوکر (لوقا ۱۲‏:‌۴۱‌‏-‌۴۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_44.mp3', '', 1761754199, 1761754199),
(33000, 'Matthew 24:45', 'Matthew', 24, 45, 'هغه وفادار او هوښیار نوکر څوک دی چې بادار یې هغه د خپلې کورنۍ د نورو نوکرانو مشر ټاکلی وي، ترڅو هغوی ته په خپل وخت ډوډۍ ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_45.mp3', '', 1761754199, 1761754199),
(33001, 'Matthew 24:46', 'Matthew', 24, 46, 'بختور دی هغه نوکر چې بادار یې راشي او هغه په خپل کار کې بوخت وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_46.mp3', '', 1761754199, 1761754199),
(33002, 'Matthew 24:47', 'Matthew', 24, 47, 'په یقین سره زه تاسو ته دا وایم چې بادار به د خپل ټول مال او جایداد واک هغه ته وسپاري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_47.mp3', '', 1761754199, 1761754199),
(33003, 'Matthew 24:48', 'Matthew', 24, 48, 'خو که هغه نوکر خراب سړی وي، نو د خپل ځان سره به ووایي چې د بادار راتګ به مې ډېر وخت ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_48.mp3', '', 1761754199, 1761754199),
(33004, 'Matthew 24:49', 'Matthew', 24, 49, 'او هغه به د نورو نوکرانو په وهلو ټکولو پیل وکړي او د شرابیانو سره به خوري او څښي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_49.mp3', '', 1761754199, 1761754199),
(33005, 'Matthew 24:50', 'Matthew', 24, 50, 'نو د هغه نوکر بادار به په هغه ورځ راشي چې نوکر به یې انتظار هم نه لري او په داسې وخت کې به راشي چې هغه به خبر هم نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_50.mp3', '', 1761754199, 1761754199),
(33006, 'Matthew 24:51', 'Matthew', 24, 51, 'نو بادار به هغه ته سخته سزا ورکړي او هغه به د منافقانو سره یوځای واچوي چې هلته به خلک ژاړي او خپل غاښونه به چیچي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew24_verse_51.mp3', '', 1761754199, 1761754199),
(33007, 'Luke 5:1', 'Luke', 5, 1, 'یوه ورځ عیسی د جنیسارت د بحیرې په غاړه ولاړ ؤ او خلکو یو بل سره ټېله کول چې ځانونه هغه ته ورسوي، ترڅو د خدای کلام واوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_1.mp3', '', 1761754199, 1761754199),
(33008, 'Luke 5:2', 'Luke', 5, 2, 'هغه ولیدل چې د بحیرې په غاړه دوه کشتۍ ولاړې وې، خو ماهيګیران ترې راښکته شوي وو او جالونه یې وینځل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_2.mp3', '', 1761754199, 1761754199),
(33009, 'Luke 5:3', 'Luke', 5, 3, 'عیسی یوې کشتۍ ته چې د شمعون وه، وروخوت او د هغه څخه یې وغوښتل چې کشتۍ د غاړې څخه لږه لېرې بوځي. عیسی په کشتۍ کې ناست ؤ او له هغه ځای څخه یې خلکو ته تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_3.mp3', '', 1761754199, 1761754199),
(33010, 'Luke 5:4', 'Luke', 5, 4, 'کله چې هغه خبرې پای ته ورسولې، نو شمعون ته یې وویل: «کشتۍ د اوبو منځ ته یو ژور ځای ته بوځه او تاسو خپل جالونه اوبو ته وغورځوئ چې ماهیان ونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_4.mp3', '', 1761754199, 1761754199);